insert into core.entity_type (code, software, name, db_table, meaning, source_id) values
    ('acad.arc', 'acad', 'ARC', 'acad.arc', 'A circular arc, counter-clockwise from start angle to end angle.', '644eed9a-bd55-5cdc-9b96-87ce906d24b6'),
    ('acad.block_record', 'acad', 'BLOCK_RECORD', 'acad.block_record', 'A block definition; model space and paper space are blocks too.', '0744cb40-2509-5421-8ccd-1dde76e21046'),
    ('acad.circle', 'acad', 'CIRCLE', 'acad.circle', 'A circle given by centre and radius.', '9560e199-1f22-5de5-b2f0-be4e6fb049ad'),
    ('acad.face3d', 'acad', '3DFACE', 'acad.face3d', 'A planar or non-planar face of three or four corners.', '9a3edac5-8539-58c0-9cea-3baa4cd2e19a'),
    ('acad.graphic_entity', 'acad', 'Common entity fields', 'acad.graphic_entity', 'Fields every AutoCAD graphic entity shares (the DXF common group codes), stored once.', '68444122-d6d5-5cb4-82fa-48db2dbecfff'),
    ('acad.insert', 'acad', 'INSERT', 'acad.insert', 'One placement of a block definition, optionally as a rectangular array.', '4ecd4520-60be-5e28-9590-e9d937214e4d'),
    ('acad.layer', 'acad', 'LAYER', 'acad.layer', 'A named layer that groups entities and carries default colour, linetype and visibility.', '4f5d4e4d-799d-566c-bab0-a934e422073d'),
    ('acad.line', 'acad', 'LINE', 'acad.line', 'A straight segment between two 3D points.', '404b4a94-3aa8-58f4-aab8-999fcf83eba1'),
    ('acad.linetype', 'acad', 'LTYPE', 'acad.linetype', 'A linetype definition (dash pattern) that layers and entities refer to.', '93155216-4ef8-5d6a-8f1b-6fd2d916e711'),
    ('acad.lwpolyline', 'acad', 'LWPOLYLINE', 'acad.lwpolyline', 'A 2D polyline; its vertices carry a bulge for arc segments.', '2d196012-da10-58cd-b6bd-b4774c666164'),
    ('acad.lwpolyline_vertex', 'acad', 'LWPOLYLINE vertex', 'acad.lwpolyline_vertex', 'One ordered vertex of an LWPOLYLINE.', '2d196012-da10-58cd-b6bd-b4774c666164'),
    ('acad.mesh', 'acad', 'MESH', 'acad.mesh', 'A subdivision mesh; vertices and faces are child rows.', 'ba5ce890-a2d8-5a21-90dd-b3382e6cdd1e'),
    ('acad.mesh_face', 'acad', 'MESH face', 'acad.mesh_face', 'One ordered face of a MESH, as indices into the vertices.', 'ba5ce890-a2d8-5a21-90dd-b3382e6cdd1e'),
    ('acad.mesh_vertex', 'acad', 'MESH vertex', 'acad.mesh_vertex', 'One ordered vertex of a MESH.', 'ba5ce890-a2d8-5a21-90dd-b3382e6cdd1e'),
    ('acad.point', 'acad', 'POINT', 'acad.point', 'A single point.', 'c71c15e0-e766-5328-b7d0-f7e1a5c21d65'),
    ('acad.text', 'acad', 'TEXT', 'acad.text', 'A single line of text.', '8915986d-f6e3-550d-b58a-356d80995120')
